style.css:
@-moz-document domain("roblox.com") {
/* Fondo general */
    body, html {
        background-color: #0b1a33 !important;  /* azul muy oscuro */
        color: #cbd6e8 !important;             /* texto azul claro */
        font-family: "Segoe UI", sans-serif !important;
    }

    /* Cabecera y barra superior */
    header, nav, .navbar, .top-nav {
        background-color: #112b55 !important;  /* azul apagado */
    }

    /* Paneles y cajas */
    .card, .container, .game-card, .section {
        background-color: #1b3b77 !important;  /* azul medio */
        border-radius: 10px !important;
        border: 1px solid #274a99 !important;
        padding: 8px !important;
        color: #cbd6e8 !important;
    }

    /* Botones */
    button, .btn, .btn-primary {
        background-color: #274a99 !important;  /* azul brillante */
        color: #e0ebff !important;
        border-radius: 6px !important;
        border: none !important;
        padding: 6px 12px !important;
    }

    button:hover, .btn:hover, .btn-primary:hover {
        background-color: #3b63c4 !important;  /* azul más claro al pasar el mouse */
    }

    /* Links */
    a, a:visited {
        color: #66a0ff !important;
        text-decoration: none !important;
    }

    a:hover {
        color: #99c2ff !important;
        text-decoration: underline !important;
    }

    /* Inputs y cajas de texto */
    input, textarea, select {
        background-color: #112b55 !important;
        color: #cbd6e8 !important;
        border: 1px solid #274a99 !important;
        border-radius: 6px !important;
        padding: 6px !important;
    }

    /* Scrollbar personalizado */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #274a99 !important;
        border-radius: 10px;
    }

    ::-webkit-scrollbar-track {
        background-color: #0b1a33 !important;
    }

    /* Menús desplegables */
    .dropdown-menu, .menu-panel {
        background-color: #1b3b77 !important;
        border: 1px solid #274a99 !important;
        border-radius: 6px !important;
    }
}
